const container=document.querySelector("#project-articles");if(!container)throw new Error("missing #project-articles");const matchKeys=(container.dataset.match||"").split(",").map(t=>t.trim().toLowerCase()).filter(Boolean);function formatDate(t){if(!t)return"";const e=new Date(t);return Number.isNaN(e.getTime())?"":e.toLocaleDateString("zh-CN",{year:"numeric",month:"2-digit",day:"2-digit"})}function escapeHtml(t){return String(t||"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;")}function render(t){const e=(t||[]).filter(t=>{const e=[t.category,t.title,t.summary,t.description,...Array.isArray(t.tags)?t.tags:[]].filter(Boolean).join(" ").toLowerCase();return matchKeys.some(t=>e.includes(t))}),n=document.querySelector("#project-count");n&&(n.textContent=e.length+" 篇"),e.length?container.innerHTML=`\n    <div class="hx-articles-grid">\n      ${e.map(t=>{const e=formatDate(t.createdAt),n=Array.isArray(t.tags)?t.tags.slice(0,4):[],a=t.summary||t.description||"";return`\n            <a class="hx-article-card" href="/notes/article/?id=${encodeURIComponent(t.id)}">\n              <div class="hx-article-meta">\n                ${e?`<span class="hx-article-date">${escapeHtml(e)}</span>`:""}\n                <span class="hx-article-cat">${escapeHtml(t.category||"项目记录")}</span>\n              </div>\n              <h3>${escapeHtml(t.title||"未命名文章")}</h3>\n              ${a?`<p>${escapeHtml(a)}</p>`:""}\n              ${n.length?`<div class="hx-article-tags">${n.map(t=>`<span>${escapeHtml(t)}</span>`).join("")}</div>`:""}\n            </a>\n          `}).join("")}\n    </div>\n  `:container.innerHTML='\n      <div class="hx-empty-state">\n        <svg viewBox="0 0 24 24" fill="none" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">\n          <path d="M4 5h16v14H4z"></path>\n          <path d="M8 9h8M8 13h5"></path>\n        </svg>\n        <h3>暂无导入文章</h3>\n        <p>前往 <a href="/studio/notion/">Notion 导入</a>，选择对应分类即可归入此页。</p>\n      </div>\n    '}async function load(){try{const t=await fetch("/api/notion/articles?public=true"),e=await t.json();render(t.ok?e.articles:[])}catch{render([])}}load();